'use strict';
// Portable copies of the existing non-speech sound effects; no generated voices.
const {gunzipSync}=require('node:zlib');
const PACKED="";
let unpacked;
function data(){return unpacked ||= JSON.parse(gunzipSync(Buffer.from(PACKED,'base64')).toString('utf8'));}
const catalog=()=>structuredClone(data().catalog);
const bundledSound=id=>data().waves[id]?Buffer.from(data().waves[id],'base64'):null;
module.exports={catalog,bundledSound};
